const ARCHIVE_SKIP = Symbol("ARCHIVE_SKIP");

function parseArchiveLine(text, lineNumber) {
  if (text.endsWith("\r")) {
    text = text.slice(0, -1);
  }

  if (text.trim() === "") {
    return ARCHIVE_SKIP;
  }

  try {
    return JSON.parse(text);
  } catch (error) {
    const syntaxError =
      error instanceof SyntaxError ? error : new SyntaxError(String(error));
    syntaxError.code = "INVALID_RECORD";
    syntaxError.line = lineNumber;
    throw syntaxError;
  }
}

async function* readArchive(chunks) {
  let iterator;
  let reachedEOF = false;
  let failed = false;

  const decoder = new TextDecoder("utf-8", { ignoreBOM: true });
  let lineParts = [];
  let lineHasBytes = false;
  let lineNumber = 1;

  try {
    iterator = chunks[Symbol.asyncIterator]();

    while (true) {
      const step = await iterator.next();

      if (step.done) {
        reachedEOF = true;

        const tail = decoder.decode();
        if (tail !== "") {
          lineParts.push(tail);
        }

        if (lineHasBytes) {
          const record = parseArchiveLine(lineParts.join(""), lineNumber);
          if (record !== ARCHIVE_SKIP) {
            yield record;
          }
        }

        return;
      }

      const bytes = step.value;
      let start = 0;

      for (let index = 0; index < bytes.length; index += 1) {
        if (bytes[index] !== 0x0a) {
          continue;
        }

        if (index > start) {
          lineHasBytes = true;
        }

        const decoded = decoder.decode(bytes.subarray(start, index), {
          stream: true
        });
        if (decoded !== "") {
          lineParts.push(decoded);
        }

        const flushed = decoder.decode();
        if (flushed !== "") {
          lineParts.push(flushed);
        }

        const currentLineNumber = lineNumber;
        lineNumber += 1;
        start = index + 1;

        const record = parseArchiveLine(
          lineParts.length === 0 ? "" : lineParts.join(""),
          currentLineNumber
        );

        lineParts = [];
        lineHasBytes = false;

        if (record !== ARCHIVE_SKIP) {
          yield record;
        }
      }

      if (start < bytes.length) {
        lineHasBytes = true;
        const decoded = decoder.decode(bytes.subarray(start), { stream: true });
        if (decoded !== "") {
          lineParts.push(decoded);
        }
      }
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (iterator !== undefined && !reachedEOF) {
      if (failed) {
        try {
          const returnMethod = iterator.return;
          if (typeof returnMethod === "function") {
            await returnMethod.call(iterator);
          }
        } catch {
          // Preserve the original read or record error.
        }
      } else {
        const returnMethod = iterator.return;
        if (typeof returnMethod === "function") {
          await returnMethod.call(iterator);
        }
      }
    }
  }
}
